import { test, expect } from '@playwright/test';

test.describe('Document Language Declaration in HTML Tag', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/document-language');
  });

  test('should display correct language when lang attribute is set', async ({ page }) => {
    // Verify the lang attribute is present on the html tag
    const htmlTag = page.locator('html');
    await expect(htmlTag).toHaveAttribute('lang', 'en-US');

    // Verify the language is displayed on the page
    const languageDisplay = page.getByText('English (US)');
    await expect(languageDisplay).toBeVisible();

    // Verify the language is used in the page content
    const content = page.getByText('Welcome to the document');
    await expect(content).toBeVisible();

    // Verify the language is used in the navigation
    const nav = page.getByRole('navigation');
    await expect(nav).toBeVisible();
  });

  test('should handle multiple language declarations and fallback gracefully', async ({ page }) => {
    // Intercept the language API call to simulate a fallback scenario
    await page.route('**/api/language', (route) => {
      route.abort();
    });

    // Verify the fallback language is displayed
    const fallbackLanguage = page.getByText('Default Language');
    await expect(fallbackLanguage).toBeVisible();

    // Verify the lang attribute is set to the fallback
    const htmlTag = page.locator('html');
    await expect(htmlTag).toHaveAttribute('lang', 'en');

    // Verify the page content is still readable
    const content = page.getByText('Welcome to the document');
    await expect(content).toBeVisible();

    // Verify the language selector is available
    const languageSelector = page.getByRole('combobox', { name: /language/i });
    await expect(languageSelector).toBeVisible();

    // Verify the language selector has options
    const options = page.getByRole('option');
    const optionCount = await options.count();
    expect(optionCount).toBeGreaterThan(1);
  });
});
